def copy_course_videos(source_course_id, destination_course_id):
    """
    Adds the destination_course_id to the videos taken from the source_course_id

    Args:
        source_course_id: The original course_id
        destination_course_id: The new course_id where the videos will be copied
    """
    if source_course_id == destination_course_id:
        return

    course_videos = CourseVideo.objects.select_related('video', 'video_image').filter(
        course_id=six.text_type(source_course_id)
    )

    for course_video in course_videos:
        destination_course_video, __ = CourseVideo.objects.get_or_create(
            video=course_video.video,
            course_id=destination_course_id
        )
        if hasattr(course_video, 'video_image'):
            VideoImage.create_or_update(
                course_video=destination_course_video,
                file_name=course_video.video_image.image.name
            )

def get_cache_stats():
    """
    Returns a list of dictionaries of all cache servers and their stats,
    if they provide stats.
    """
    cache_stats = []
    for name, _ in six.iteritems(settings.CACHES):
        cache_backend = caches[name]

        try:
            cache_backend_stats = cache_backend._cache.get_stats()
        except AttributeError:  # this backend doesn't provide stats
            logger.info(
                'The memcached backend "{0}" does not support or '
                'provide stats.'.format(name)
            )
            continue

        for address, stats in cache_backend_stats:
            cache_stats.append(
                {'name': name, 'address': address, 'stats': stats}
            )
    return cache_stats

def serialized(func):
    """Write a serializer by yielding each line of output"""

    @wraps(func)
    def wrapper(*args, **kwargs):
        return '\n'.join(
            ' '.join(parts) if isinstance(parts, tuple) else parts
            for parts in func(*args, **kwargs)
        )

    return wrapper

def create_pr_message(self, skill_git: Git, skill_repo: Repository) -> tuple:
        """Reads git commits from skill repo to create a list of changes as the PR content"""
        title = 'Upgrade ' + self.skill.name
        body = body_template.format(
            skill_name=self.skill.name,
            commits='\n'.join(
                ' - [{}]({})'.format(
                    skill_git.show('-s', sha, format='%s'),
                    skill_repo.get_commit(sha).html_url
                )
                for sha in skill_git.rev_list(
                    '--ancestry-path', '{}..{}'.format(self.skill.entry.sha, 'HEAD')
                ).split('\n')
            )
        )
        return title, body

def ship_move(ship, x, y, speed):
    """Moves SHIP to the new location X,Y."""
    click.echo('Moving ship %s to %s,%s with speed %s' % (ship, x, y, speed))

def allowed_transitions():
    """Get target states allowed for the current state."""
    try:
        sdp_state = SDPState()
        return sdp_state.allowed_target_states[sdp_state.current_state]
    except KeyError:
        LOG.error("Key Error")
        return dict(state="KeyError", reason="KeyError")

def get_current_state():
    """Return the SDP State and the timestamp for when it was updated."""
    sdp_state = SDPState()
    errval, errdict = _check_status(sdp_state)
    if errval == "error":
        LOG.debug(errdict['reason'])
        return dict(
            current_state="unknown",
            last_updated="unknown",
            reason=errdict['reason']
        )
    LOG.debug('Current State: %s', sdp_state.current_state)
    LOG.debug('Current State last updated: %s',
              sdp_state.current_timestamp.isoformat())
    return dict(
        current_state=sdp_state.current_state,
        last_updated=sdp_state.current_timestamp.isoformat()
    ), HTTPStatus.OK

def processing_block_list():
    """Return the list of processing blocks known to SDP."""
    pb_list = ProcessingBlockList()
    return dict(active=pb_list.active,
                completed=pb_list.completed,
                aborted=pb_list.aborted)

def scheduling_blocks():
    """Return list of Scheduling Block instances known to SDP."""
    sbi_list = SchedulingBlockInstanceList()
    return dict(active=sbi_list.active,
                completed=sbi_list.completed,
                aborted=sbi_list.aborted)

def catch_all(path):
    """Catch all path - return a JSON 404 """
    return (dict(error='Invalid URL: /{}'.format(path),
                 links=dict(root='{}{}'.format(request.url_root, PREFIX[1:]))),
            HTTPStatus.NOT_FOUND)

def get_active() -> List[str]:
        """Return the list of active subarrays."""
        active = []
        for i in range(__num_subarrays__):
            key = Subarray.get_key(i)
            if DB.get_hash_value(key, 'active').upper() == 'TRUE':
                active.append(Subarray.get_id(i))
        return active

def get_inactive() -> List[str]:
        """Return the list of inactive subarrays."""
        inactive = []
        for i in range(__num_subarrays__):
            key = Subarray.get_key(i)
            if DB.get_hash_value(key, 'active').upper() == 'FALSE':
                inactive.append(Subarray.get_id(i))
        return inactive

def reduce_sequences(object_a, object_b):
    """Performs an element-wise addition of sequences into a new list.

    Both sequences must have the same length, and the addition operator must be
    defined for each element of the sequence.
    """
    def is_seq(obj):
        """Returns true if the object passed is a sequence."""
        return hasattr(obj, "__getitem__") or hasattr(obj, "__iter__")
    if object_a is None or object_b is None:
        return None
    elif is_seq(object_a) and is_seq(object_b):
        reduced = []
        for element_a, element_b in zip(object_a, object_b):
            if element_a is not None and element_b is not None:
                reduced.append(element_a + element_b)
            else:
                reduced.append(None)
        return reduced
    else:
        return object_a + object_b

def clear_db():
    """Clear the entire db."""
    cursor = '0'
    while cursor != 0:
        cursor, keys = DB.scan(cursor, match='*', count=5000)
        if keys:
            DB.delete(*keys)

def get_scheduling_block_ids():
    """Return list of scheduling block IDs"""
    ids = [key.split('/')[-1]
           for key in DB.keys(pattern='scheduling_block/*')]
    return sorted(ids)

def get_sub_array_ids():
    """Return list of sub-array Id's currently known to SDP"""
    ids = set()
    for key in sorted(DB.keys(pattern='scheduling_block/*')):
        config = json.loads(DB.get(key))
        ids.add(config['sub_array_id'])
    return sorted(list(ids))

def get_subarray_sbi_ids(sub_array_id):
    """Return list of scheduling block Id's associated with the given
    sub_array_id
    """
    ids = []
    for key in sorted(DB.keys(pattern='scheduling_block/*')):
        config = json.loads(DB.get(key))
        if config['sub_array_id'] == sub_array_id:
            ids.append(config['id'])
    return ids

def get_processing_block_ids():
    """Return an array of Processing Block ids"""
    ids = []
    for key in sorted(DB.keys(pattern='scheduling_block/*')):
        config = json.loads(DB.get(key))
        for processing_block in config['processing_blocks']:
            ids.append(processing_block['id'])
    return ids

def get_processing_block(block_id):
    """Return the Processing Block Configuration for the specified ID"""
    identifiers = block_id.split(':')
    scheduling_block_id = identifiers[0]
    scheduling_block_config = get_scheduling_block(scheduling_block_id)
    for processing_block in scheduling_block_config['processing_blocks']:
        if processing_block['id'] == block_id:
            return processing_block
    raise KeyError('Unknown Processing Block id: {} ({})'
                   .format(identifiers[-1], block_id))

def _get_events_list(object_key: str) -> List[str]:
    """Get list of event ids for the object with the specified key.

    Args:
        object_key (str): Key of an object in the database.

    """
    return DB.get_list(_keys.events_list(object_key))

def pb_config(self):
        """Return the PB configuration."""
        pb = ProcessingBlock(self._pb_id)
        return json.dumps(pb.config)

def current_timestamp(self) -> datetime:
        """Get the current state timestamp."""
        timestamp = DB.get_hash_value(self._key, 'current_timestamp')
        return datetime_from_isoformat(timestamp)

def target_timestamp(self) -> datetime:
        """Get the target state timestamp."""
        timestamp = DB.get_hash_value(self._key, 'target_timestamp')
        return datetime_from_isoformat(timestamp)

def get_sched_block_instance_ids(self):
        """Get unordered list of scheduling block ids"""

        # Initialise empty list
        scheduling_block_ids = []

        # Pattern used to search scheduling block ids
        pattern = 'scheduling_block:*'
        block_ids = self._db.get_ids(pattern)

        for block_id in block_ids:
            if 'processing_block' not in block_id:
                id_split = block_id.split(':')[-1]
                scheduling_block_ids.append(id_split)
        return sorted(scheduling_block_ids)

def get_sub_array_sbi_ids(self, sub_array_id):
        """Get Scheduling Block Instance ID associated with sub array id"""
        _ids = []
        sbi_ids = self.get_sched_block_instance_ids()
        for details in self.get_block_details(sbi_ids):
            if details['sub_array_id'] == sub_array_id:
                _ids.append(details['id'])
        return sorted(_ids)

def get_block_details(self, block_ids):
        """Get details of scheduling or processing block

        Args:
            block_ids (list): List of block IDs
        """
        # Convert input to list if needed
        if not hasattr(block_ids, "__iter__"):
            block_ids = [block_ids]

        for _id in block_ids:
            block_key = self._db.get_block(_id)[0]
            block_data = self._db.get_all_field_value(block_key)
            # NOTE(BM) unfortunately this doesn't quite work for keys where \
            # the value is a python type (list, dict etc) \
            # The following hack works for now but is probably not infallible
            for key in block_data:
                for char in ['[', '{']:
                    if char in block_data[key]:
                        block_data[key] = ast.literal_eval(
                            str(block_data[key]))
            yield block_data

def update_value(self, block_id, field, value):
        """"Update the value of the given block id and field"""
        block_name = self._db.get_block(block_id)
        for name in block_name:
            self._db.set_value(name, field, value)

def _add_status(scheduling_block):
        """This function adds status fields to all the section
        in the scheduling block instance"""
        scheduling_block['status'] = "created"
        for block in scheduling_block:
            if isinstance(scheduling_block[block], list):
                for field in scheduling_block[block]:
                    field['status'] = 'created'
        return scheduling_block

def _split_sched_block_instance(self, scheduling_block):
        """Split the scheduling block data into multiple names
        before adding to the configuration database"""

        # Initialise empty list
        _scheduling_block_data = {}
        _processing_block_data = {}
        _processing_block_id = []

        for block in scheduling_block:
            values = scheduling_block[block]

            if block != 'processing_blocks':
                _scheduling_block_data[block] = values
            else:
                # Check if there is a processing block that already exits in
                # the database
                processing_block_id = self.get_processing_block_ids()

                for value in values:
                    if value['id'] not in processing_block_id:
                        _processing_block_data = values
                    else:
                        raise Exception("Processing block already exits",
                                        value['id'])

        # Adding processing block id to the scheduling block list
        for block_id in _processing_block_data:
            _processing_block_id.append(block_id['id'])
        _scheduling_block_data['processing_block_ids'] = _processing_block_id

        return _scheduling_block_data, _processing_block_data

def disable_logger(logger_name: str, propagate: bool = False):
    """Disable output for the logger of the specified name."""
    log = logging.getLogger(logger_name)
    log.propagate = propagate
    for handler in log.handlers:
        log.removeHandler(handler)

def configure(self, sbi_config: str):
        """Configure an SBI for this subarray.

        Args:
            sbi_config (str): SBI configuration JSON

        Returns:
            str,

        """
        # print(sbi_config)
        config_dict = json.loads(sbi_config)
        self.debug_stream('SBI configuration:\n%s',
                          json.dumps(config_dict, indent=2))
        try:
            sbi = Subarray(self.get_name()).configure_sbi(config_dict)
        except jsonschema.exceptions.ValidationError as error:
            return json.dumps(dict(path=error.absolute_path.__str__(),
                                   schema_path=error.schema_path.__str__(),
                                   message=error.message), indent=2)
        except RuntimeError as error:
            return json.dumps(dict(error=str(error)), indent=2)
        return 'Accepted SBI: {}'.format(sbi.id)

def datetime_from_isoformat(value: str):
    """Return a datetime object from an isoformat string.

    Args:
        value (str): Datetime string in isoformat.

    """
    if sys.version_info >= (3, 7):
        return datetime.fromisoformat(value)

    return datetime.strptime(value, '%Y-%m-%dT%H:%M:%S.%f')

def always_executed_hook(self):
        """Run for each command."""
        _logT = self._devProxy.get_logging_target()
        if 'device::sip_sdp_logger' not in _logT:
            try:
                self._devProxy.add_logging_target('device::sip_sdp/elt/logger')
                self.info_stream("Test of Tango logging from "
                                 "'tc_tango_master'")

            except Exception as e:
                LOG.debug('Failed to setup Tango logging %s', e )

def _get_service_state(service_id: str):
        """Get the Service state object for the specified id."""
        LOG.debug('Getting state of service %s', service_id)
        services = get_service_id_list()
        service_ids = [s for s in services if service_id in s]
        if len(service_ids) != 1:
            return 'Service not found! services = {}'.format(str(services))
        subsystem, name, version = service_ids[0].split(':')
        return ServiceState(subsystem, name, version)

def target_sdp_state(self, state):
        """Update the target state of SDP."""
        LOG.info('Setting SDP target state to %s', state)
        if self._sdp_state.current_state == state:
            LOG.info('Target state ignored, SDP is already "%s"!', state)
        if state == 'on':
            self.set_state(DevState.ON)
        if state == 'off':
            self.set_state(DevState.OFF)
        if state == 'standby':
            self.set_state(DevState.STANDBY)
        if state == 'disable':
            self.set_state(DevState.DISABLE)
        self._sdp_state.update_target_state(state)

def _set_master_state(self, state):
        """Set the state of the SDPMaster."""
        if state == 'init':
            self._service_state.update_current_state('init', force=True)
            self.set_state(DevState.INIT)

        elif state == 'on':
            self.set_state(DevState.ON)
            self._service_state.update_current_state('on')

def _scheduling_block_ids(num_blocks, start_id, project):
    """Generate Scheduling Block instance ID"""
    for i in range(num_blocks):
        _root = '{}-{}'.format(strftime("%Y%m%d", gmtime()), project)
        yield '{}-sb{:03d}'.format(_root, i + start_id), \
              '{}-sbi{:03d}'.format(_root, i + start_id)

