def create_from_names(cls, property_names):
        """
        Create a Property instance from a list of well-known property names
        @param property_names: a non-empty list of property names
        """
        assert property_names

        if len(property_names) == 1:
            name = property_names[0]
            subproperties = None
        else:
            name = (_PROP_MEMSAFETY if set(property_names) == _MEMSAFETY_SUBPROPERTIES
                    else "unknown property")
            subproperties = list(property_names)

        is_well_known = name in _VALID_RESULTS_PER_PROPERTY.keys()
        is_svcomp = is_well_known and (_PROP_SAT not in property_names)

        return cls(None, is_well_known, is_svcomp, name, subproperties)

def open_url_seekable(path_url, mode='rt'):
    """Open a URL and ensure that the result is seekable,
    copying it into a buffer if necessary."""

    logging.debug("Making request to '%s'", path_url)
    response = urllib.request.urlopen(path_url)
    logging.debug("Got response %s", response.info())

    try:
        response.seek(0)
    except (IOError, AttributeError):
        # Copy into buffer to allow seeking.
        response = io.BytesIO(response.read())
    if "b" in mode:
        return response
    else:
        return io.TextIOWrapper(response)

def format_options(options):
    '''Helper function for formatting the content of the options line'''
    # split on one of the following tokens: ' -' or '[[' or ']]'
    lines = ['']
    for token in re.split(r'( -|\[\[|\]\])', options):
        if token in ['[[',']]']:
            lines.append(token)
            lines.append('')
        elif token == ' -':
            lines.append(token)
        else:
            lines[-1] += token
    # join all non-empty lines and wrap them into 'span'-tags
    return '<span style="display:block">' + '</span><span style="display:block">'.join(line for line in lines if line.strip()) + '</span>'

def get_column_type(column, column_values):
    """
    Returns the type of the given column based on its row values on the given RunSetResult.
    @param column: the column to return the correct ColumnType for
    @param column_values: the column values to consider
    @return: a tuple of a type object describing the column - the concrete ColumnType is stored in the attribute 'type',
        the display unit of the column, which may be None,
        the source unit of the column, which may be None,
        and the scale factor to convert from the source unit to the display unit.
        If no scaling is necessary for conversion, this value is 1.
    """

    try:
        return _get_column_type_heur(column, column_values)
    except util.TableDefinitionError as e:
        logging.error("Column type couldn't be determined: {}".format(e.message))
        return ColumnType.text, None, None, 1

